import {PORTRAITS} from './portraits.js';
import {embedded,hostedRequest,entryURL,clearIncomingHash} from './transport.js';
import {CATS,LABELS,KEYS,SLOTS,total,stats,value,format,compare,today,weekDates,autoLineup,eligible,baseline,zscore,closeWeights,nameKey,officialWeekScore,canEditPrediction} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(embedded)document.documentElement.classList.add('embedded-app');
const PAGES=[['overview','📊','總覽'],['watch','⭐','球員觀察室'],['planner','📅','每週補強'],['trade','🤝','交易分析'],['strategy','🎯','九項策略'],['sim','🏀','模擬對局'],['calendar','📆','賽程週曆'],['results','🏆','比賽戰況'],['data','🗂️','資料中心'],['settings','⚙️','設定']];
const fresh=()=>({schema:1,files:{'league_rosters.json':{teams:{},free:[],capacity:14,revision:0},'player_watchlist.json':{ids:[]},'simulations.json':{}},prefs:{}});
const S={page:'overview',team:'',date:today(),league:new URL(entryURL()).searchParams.get('league')||'',payload:fresh(),revision:0,dirty:false,session:null,model:null,players:[],pool:{},base:null,strategySeason:'2026-27',strategyData:null,strategyError:'',strategyLoading:false,strategyPosition:'',strategyIncludeOwned:false,watchSearch:'',watchScope:'team',detail:null,sim:null,simDay:0,simSide:'my',opponent:'',calendarMode:'all',weights:{},pending:false,cloudReady:false,cloudError:'',generation:0};
let toastTimer,cloudTimer,saveChain=Promise.resolve();
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(path,{method='GET',body}={}){if(embedded)return hostedRequest(path,{method,body});const response=await fetch(path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':S.session?.csrf||''},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error('連線中斷，請稍後再試');}if(!response.ok){const error=Error(data.error||'操作未完成');error.status=response.status;throw error;}return data;}
function localKey(){return 'fgm-pwa-v1:'+String(S.session?.user?.sub||'guest')+':'+(S.league||'unassigned');}
function persist(){try{if(S.league)localStorage.setItem('fgm-pwa-active:'+String(S.session?.user?.sub||'guest'),S.league);localStorage.setItem(localKey(),JSON.stringify({payload:S.payload,revision:S.revision,dirty:S.dirty,team:S.team,date:S.date,theme:document.body.classList.contains('dark')}));}catch{toast('本機保存失敗，請先下載備份');throw Error('本機保存不可用');}}
function restore(){try{if(!S.league)S.league=localStorage.getItem('fgm-pwa-active:'+String(S.session?.user?.sub||'guest'))||'';const saved=JSON.parse(localStorage.getItem(localKey())||'null');if(saved){S.payload=saved.payload;if(!S.league&&/^\d{1,10}$/.test(String(S.payload.files?.['league_rosters.json']?.sync_league||'')))S.league=String(S.payload.files['league_rosters.json'].sync_league);S.revision=saved.revision||0;S.dirty=!!saved.dirty;S.team=saved.team||'';S.date=saved.date||today();document.body.classList.toggle('dark',!!saved.theme);}}catch{toast('本機紀錄無法讀取，原資料保留');}}
function league(){return S.payload.files['league_rosters.json']||{teams:{}};}
function teams(){return Object.keys(league().teams||{});}
function teamName(t){return league().team_names?.[t]||t;}
function roster(t=S.team){return league().teams?.[t]||[];}
function archives(){return league().daily_rosters||{};}
function stars(){return S.payload.files['player_watchlist.json']?.ids||[];}
function pkey(p){return String(p.id??p.PLAYER_ID??'missing:'+nameKey(p.name));}
function profile(p){return S.pool[String(p.id??p.PLAYER_ID)]||S.players.find(x=>nameKey(x.PLAYER_NAME)===nameKey(p.name||''));}
function uniqueRoster(rows){const found=new Map();for(const row of rows){const name=String(row.name||row.PLAYER_NAME||'').toLowerCase().replace(/[^a-z0-9]/g,''),id=String(row.nba_id||PORTRAITS[name]||row.id||'name:'+name);if(!found.has(id))found.set(id,{...row});else{const saved=found.get(id);for(const key of ['id','nba_id','team','eligible'])if(!saved[key]||Array.isArray(saved[key])&&!saved[key].length)if(row[key])saved[key]=row[key];}}return [...found.values()];}
function photo(p){const id=PORTRAITS[String(p.name||p.PLAYER_NAME||'').toLowerCase().replace(/[^a-z0-9]/g,'')]||String(p.nba_id??p.id??p.PLAYER_ID??'');return /^\d+$/.test(id)?`<img class="portrait" loading="lazy" src="https://cdn.nba.com/headshots/nba/latest/260x190/${id}.png" alt="">`:'<span class="portrait"></span>';}
function statline(s){return `<div class="statline">${CATS.map((c,i)=>`<span><small>${LABELS[i]}</small><b>${s?esc(format(value(s,c),c)):'—'}</b></span>`).join('')}</div>`;}
function row(p,s,extra=''){return `<div class="player-row">${photo(p)}<div class="row between"><span class="player-name">${esc(p.name||p.PLAYER_NAME)}<small class="position">${esc((p.eligible||[]).join('/'))}</small></span>${extra}</div>${statline(s)}</div>`;}
function section(title,body){return `<section class="card"><h3>${esc(title)}</h3>${body}</section>`;}
function empty(text='先同步或匯入聯盟名單'){return `<div class="empty"><p>${esc(text)}</p><button class="primary" data-action="go" data-page="settings">設定同步</button><button data-action="import">匯入備份</button></div>`;}
function select(id,items,selected,label){return `<div><label for="${id}">${esc(label)}</label><select id="${id}">${items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;}
function dateControl(id='date',value=S.date){return `<div><label for="${id}">日期</label><input id="${id}" type="date" value="${esc(value)}"></div>`;}
function opponent(){const week=league().matchup_schedule?.weeks?.find(w=>w.start<=S.date&&w.end>=S.date);const official=week?.opponents?.[S.team];return teams().includes(S.opponent)&&S.opponent!==S.team?S.opponent:official||teams().find(t=>t!==S.team)||'';}
function weekActual(team){let missing=0,games=0;const byId=new Map();for(const d of weekDates(S.date).filter(d=>d<=today())){const rows=archives()[d]?.teams?.[team];if(!rows){missing++;continue;}for(const p of rows){if(p.status!=='active')continue;if(p.daily_stats==null)continue;games++;const key=pkey(p);const old=byId.get(key)||{p,values:[]};old.values.push(stats(p.daily_stats));byId.set(key,old);}}return {missing,games,rows:[...byId.values()].map(x=>({p:x.p,stats:total(x.values)})),totals:total([...byId.values()].flatMap(x=>x.values))};}
function scoreTable(a,b){const c=compare(a,b);return `<table><thead><tr><th>項目</th><th>我方</th><th>對手</th><th></th></tr></thead><tbody>${c.rows.map((r,i)=>`<tr><td>${LABELS[i]}</td><td>${format(r.a,r.cat)}</td><td>${format(r.b,r.cat)}</td><td>${r.result==null?'—':r.result===1?'🟢':r.result===-1?'🟠':'➖'}</td></tr>`).join('')}</tbody></table>`;}
function scoreCard(a,b,other,complete=true){const c=complete?compare(a,b):null;return `<div class="card score"><strong><span class="mine">${c?.wins??'—'}</span> – <span class="enemy">${c?.losses??'—'}</span></strong><p>vs ${esc(teamName(other))}</p></div>`;}
function renderContext(){const ts=teams();if(!ts.includes(S.team))S.team=S.payload.prefs._my_team&&ts.includes(S.payload.prefs._my_team)?S.payload.prefs._my_team:ts[0]||'';$('#team').innerHTML=ts.length?ts.map(t=>`<option value="${esc(t)}" ${t===S.team?'selected':''}>${esc(teamName(t))}</option>`).join(''):'<option value="">尚無名單</option>';$('#cloud-state').dataset.action=S.session?.user?'cloud':'login';$('#drawer-cloud').dataset.action=S.session?.user?'cloud':'login';$('#drawer-cloud').textContent=S.session?.user?'☁️ 同步 Google Drive':'☁️ 登入 Google';$('#cloud-state').textContent=S.cloudError?'☁️ 未完成':S.pending?'☁️ 保存中':S.dirty?'本機已存':S.session?.user?`☁️ ${S.revision}`:'☁️ 登入';$('#account-name').textContent=S.session?.user?'☁️ '+S.session.user.name:'本機紀錄';}
function setDrawer(open){document.body.classList.toggle('drawer-open',open);$('#drawer').inert=!open;$('#scrim').hidden=!open;$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'收起選單':'開啟選單');}
function rememberedPage(){try{const page=sessionStorage.getItem("fgm-page:"+S.league);return PAGES.some(p=>p[0]===page)?page:"overview";}catch{return "overview";}}
function navigate(page,{history=true}={}){if(!PAGES.some(p=>p[0]===page))return;S.page=page;try{sessionStorage.setItem('fgm-page:'+S.league,page);}catch{}S.detail=null;setDrawer(false);if(history)window.history.pushState({page},'',location.pathname+location.search+'#page='+page);render();if(page==='sim'||page==='planner')refreshSimStatus();if(page==='strategy'&&!S.strategyData)loadStrategySeason();(embedded?document.body:window).scrollTo(0,0);$('#main').focus({preventScroll:true});}
function render(){renderContext();document.body.classList.toggle('planner-tray-open',S.page==='planner'&&plannerTrayOpen);document.querySelector('.context').classList.toggle('planner-context',S.page==='planner');$('#title').textContent=PAGES.find(p=>p[0]===S.page)?.[2]||'總覽';$('#navigation').innerHTML=PAGES.map(([id,icon,title])=>`<button data-page="${id}" ${S.page===id?'aria-current="page"':''}><span>${icon}</span>${title}</button>`).join('');const renderers={overview:overviewPage,watch:watchPage,planner:plannerPage,trade:tradePage,strategy:strategyPage,sim:simPage,calendar:calendarPage,results:resultsPage,data:dataPage,settings:settingsPage};$('#main').innerHTML=renderers[S.page]();}
function actualScoreCard(){const official=officialWeekScore(league(),S.payload.files['league_results.json'],S.team,S.date);if(official){const time=new Date(official.stamp);const stamp=Number.isNaN(time.getTime())?'':new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(time);return `<div class="card score"><strong><span class="mine">${official.wins}</span> – <span class="enemy">${official.losses}</span></strong><p>vs ${esc(teamName(official.opponent))}</p></div>`+`<small>已保存的 Yahoo 比分 · ${esc(stamp)} 同步（台灣時間）</small>`;}return `<div class="card score"><strong>— – —</strong><p>vs ${esc(teamName(opponent()))}</p><small>尚未同步 Yahoo 官方週比分</small></div>`;}
function addQuotaKey(){return 'stream_adds_'+S.team+'_'+weekDates(S.date)[0];}
function overviewPage(){if(!teams().length)return empty();const a=weekActual(S.team),other=opponent(),b=weekActual(other);const ranked=[...a.rows].sort((x,y)=>zscore(y.stats,S.base)-zscore(x.stats,S.base));let body=`<div class="field-row overview-period">${dateControl()}<div><label>範圍</label><div class="tag">當週實績</div></div></div><div><label>本週剩餘 add</label><div class="tag">${league().yahoo_adds?.[S.team]?.week===weekDates(S.date)[0]?league().yahoo_adds[S.team].remaining:'—'}</div></div>`+actualScoreCard();if(a.missing)body+=`<small>缺 ${a.missing} 天排陣；不以預測補實績。</small>`;if(ranked.length){const top=ranked[0];body+=section('九項貢獻',`<div class="hero"><div><small>本週</small><h2>${esc(top.p.name)}</h2><span class="tag">${a.games} 場球員實績</span></div>${photo(top.p)}</div>${statline(top.stats)}`);}const injured=roster().filter(p=>p.status==='IL');body+=section('球員產量',a.rows.length?a.rows.map(x=>row(x.p,x.stats,`<button class="star" data-action="star" data-id="${esc(pkey(x.p))}" aria-label="追蹤球員">${stars().includes(pkey(x.p))?'★':'☆'}</button>`)).join(''):'<small>尚無當週實績。</small>');if(injured.length)body+=section('傷兵',injured.map(p=>row(p,null)).join(''));return body;}
function watchPage(){const rosterIds=new Set(roster().map(pkey));const rows=S.players.filter(p=>S.watchScope==='stars'?stars().includes(pkey(p)):S.watchScope==='all'||rosterIds.has(pkey(p))).filter(p=>nameKey(p.PLAYER_NAME).includes(nameKey(S.watchSearch)));return `<div class="field-row"><div><label for="watch-search">搜尋</label><input id="watch-search" type="search" value="${esc(S.watchSearch)}" autocomplete="off"></div>${select('watch-scope',[['team','我的球員'],['stars','星號'],['all','全部']],S.watchScope,'範圍')}</div><div class="player-grid">${rows.slice(0,100).map(p=>`<article class="player-tile">${photo(p)}<div class="player-name">${esc(p.PLAYER_NAME)}</div><small>${esc(p.TEAM_ABBREVIATION)} <button class="star" data-action="star" data-id="${p.PLAYER_ID}" aria-label="追蹤">${stars().includes(pkey(p))?'★':'☆'}</button></small><button data-action="news" data-id="${p.PLAYER_ID}">⋯</button></article>`).join('')}</div>${!rows.length?'<div class="empty">沒有符合的球員</div>':''}`;}
async function loadStrategySeason(){if(S.strategyLoading)return;S.strategyLoading=true;S.strategyError='';try{S.strategyData=await api('/api/strategy-stats?season='+S.strategySeason);}catch(e){S.strategyError=e.message;toast(e.message);}finally{S.strategyLoading=false;if(S.page==='strategy')render();}}
function fantasyOwner(id){const t=teams().find(t=>roster(t).some(p=>pkey(p)===String(id)));return t?teamName(t):'歸屬待確認';}
function strategyPage(){const selector=select('strategy-season',[['2026-27','2026–27 本季'],['blended-25','上季最後25場＋本季全部'],['2025-26','2025–26 上季']],S.strategySeason,'數據賽季');if(!S.strategyData)return selector+(S.strategyError?`<p>${esc(S.strategyError)}</p><button data-action="strategy-retry">重新載入</button>`:'<p>載入場均…</p>');const strategyBase=baseline(S.strategyData.players,S.strategySeason==='2026-27'?1:10),weights=S.weights,ranked=S.strategyData.players.filter(p=>(S.strategyIncludeOwned||!roster().some(r=>pkey(r)===String(p.PLAYER_ID)))&&p.GP>=(S.strategySeason==='2026-27'?1:10)&&(!S.strategyPosition||(league().player_meta?.[String(p.PLAYER_ID)]?.eligible||teams().flatMap(t=>roster(t)).find(r=>pkey(r)===String(p.PLAYER_ID))?.eligible||[]).includes(S.strategyPosition))).map(p=>({p,z:zscore(p,strategyBase,weights)})).sort((a,b)=>b.z-a.z);return selector+`<small>${esc(S.strategyData.season)} 場均 · ${esc(S.strategyData.fetchedAt)}</small>`+section('權重',`<div class="field-row three">${CATS.map((c,i)=>`<div><label for="weight-${c}">${LABELS[i]}</label><input id="weight-${c}" type="number" min="0" max="10" step=".5" value="${weights[c]??1}"></div>`).join('')}</div><button class="primary" data-action="apply-weights">套用權重</button><small>所選賽季場均 Z-score，TO 反向。</small>`)+section('球員排名',`${select('strategy-position',[['','全部位置'],...['PG','SG','SF','PF','C'].map(p=>[p,p])],S.strategyPosition,'指定位置')}<button data-action="strategy-owned" aria-pressed="${S.strategyIncludeOwned}">${S.strategyIncludeOwned?'✓ ':''}包含我的球員</button><button data-action="strategy-reset">重設篩選</button>${!ranked.length?'<p>沒有符合位置的球員，請重設篩選。</p>':''}<div class="rank-list">${ranked.map(({p,z},i)=>`<div class="row"><span class="rank">${i+1}</span><span class="player-name">${esc(p.PLAYER_NAME)}</span><span class="strategy-owner">${esc(fantasyOwner(p.PLAYER_ID))}</span><b>${z.toFixed(2)}</b><button class="star" data-action="star" data-id="${p.PLAYER_ID}" aria-label="追蹤">${stars().includes(pkey(p))?'★':'☆'}</button></div>`).join('')}</div>`);}
function weeklyPrediction(team,extra=null,drop=null){const days=weekDates(S.date),players=[...roster(team).filter(p=>p.status!=='IL'&&pkey(p)!==drop),...(extra?[extra]:[])];const values=[],counts={};let missing=0;for(const d of days){if(d<=today()){const rows=archives()[d]?.teams?.[team];if(!rows){missing++;continue;}for(const p of rows)if(p.status==='active'&&p.daily_stats!=null){values.push(stats(p.daily_stats));counts[pkey(p)]=(counts[pkey(p)]||0)+1;}continue;}const lineup=autoLineup(players,d,S.model.schedule);for(const id of Object.values(lineup).filter(Boolean)){const p=players.find(p=>p.id===id),base=profile(p);if(base){values.push(stats(base));counts[id]=(counts[id]||0)+1;}}}return {stats:total(values),games:values.length,counts,missing};}
let plannerStart=today(),plannerDrops=[],plannerResult=null,plannerBusy=false,plannerResearch=null,plannerRemaining=null,plannerTrayOpen=false;
function plannerCalendar(){const dates=weekDates(plannerStart),schedule=S.model.schedule;return `<details class="planner-calendar" ${window.matchMedia('(min-width:1000px)').matches?'open':''}><summary>📅 賽程 · B2B</summary><table class="calendar"><thead><tr><th></th>${dates.map((d,i)=>`<th>${['一','二','三','四','五','六','日'][i]}</th>`).join('')}</tr></thead><tbody>${Object.keys(NBA_LOGO_IDS).map(t=>`<tr><td><img width="24" height="24" src="https://cdn.nba.com/logos/nba/${NBA_LOGO_IDS[t]}/primary/L/logo.svg" alt="${t}"></td>${dates.map(d=>{const games=schedule[t]||[],yes=games.includes(d),stamp=new Date(d+'T12:00:00Z'),prev=new Date(stamp),next=new Date(stamp);prev.setUTCDate(prev.getUTCDate()-1);next.setUTCDate(next.getUTCDate()+1);const back=yes&&(games.includes(prev.toISOString().slice(0,10))||games.includes(next.toISOString().slice(0,10)));return `<td class="${back?'b2b':''}">${yes?(back?'✓':'●'):'·'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></details>`;}
function plannerPage(){
 if(!teams().length)return empty();if(plannerResearch===null)plannerResearch=!league().free?.length;S.date=plannerStart;S.opponent=league().matchup_schedule?.weeks?.find(w=>w.start<=S.date&&w.end>=S.date)?.opponents?.[S.team]||'';ensureSim();
 const quota=league().yahoo_adds?.[S.team],week=weekDates(plannerStart),remaining=plannerRemaining??(quota?.week===week[0]?quota.remaining:S.payload.prefs['stream_adds_'+S.team+'_'+week[0]]??4);
 const officialOpponent=league().matchup_schedule?.weeks?.find(w=>w.start<=S.date&&w.end>=S.date)?.opponents?.[S.team];let html=`<h2>1 · 球隊與週次</h2><div class="field-row">${select('planner-team',teams().map(t=>[t,teamName(t)]),S.team,'球隊')}<div><label>週次</label><div class="row"><button data-action="planner-week" data-offset="-7" aria-label="上一週">‹</button><b>${week[0].slice(5)} — ${week[6].slice(5)}</b><button data-action="planner-week" data-offset="7" aria-label="下一週">›</button></div></div></div><p>對手 · ${officialOpponent?esc(teamName(officialOpponent)):'此週尚未同步對手'}</p>`;
 html+=section('2 · 可丟棄球員',`<div class="rotation-portraits">${uniqueRoster(roster()).map(p=>`<button class="rotation-pick ${plannerDrops.includes(pkey(p))?'selected':''}" data-action="planner-drop" data-id="${esc(pkey(p))}" aria-label="${esc(p.name)}${p.status==='IL'?' · 傷兵':''}" aria-pressed="${plannerDrops.includes(pkey(p))}">${photo(p)}${p.status==='IL'?'<span class="injury">IL</span>':''}</button>`).join('')}</div><div class="planner-quota"><label for="planner-remaining">剩餘 add</label><input id="planner-remaining" type="number" min="0" max="4" value="${remaining}"></div><details><summary>候選設定</summary><label class="planner-research"><input type="checkbox" id="planner-research" ${plannerResearch?'checked':''}>包含歸屬待確認候選</label></details>`);
 html+=`<h2>3 · 調整週 roster</h2><div class="planner-workspace"><div class="planner-simulator">${simPage(true)}</div>${plannerCalendar()}</div><button class="primary" data-action="planner-analyze" ${plannerBusy||week[6]<today()?'disabled':''}>${plannerBusy?'規劃中…':'規劃整週補強流程'}</button>`;
 const r=plannerResult;if(!r)return html+'<div id="planner-analysis"><h2>4 · 推薦球員與整週流程</h2><p class="muted">選好可丟棄球員後，按「規劃整週補強流程」。</p></div>';
 const windows=ws=>{const byDay=new Map();for(const w of ws){const [d,p]=Array.isArray(w)?w:[w.date,w.position];if(!byDay.has(d))byDay.set(d,new Set());byDay.get(d).add(p);}return [...byDay].map(([d,ps])=>esc(d.slice(5)+(ps.has('UTIL')?' 不限位置':' '+[...ps].join('/')))).join('、');};
 html+='<div id="planner-analysis"><h2>4 · 推薦球員與整週流程</h2>';if(r.issues?.length)return html+r.issues.map(x=>`<p class="error">${esc(x)}</p>`).join('')+'</div>';
 html+=section('整週補強流程',(r.sequences||[]).map((p,i)=>`<article class="card"><h3>流程 ${i+1} · ${p.adds} 次 add · 淨增 ${p.net_games>=0?'+':''}${p.net_games} 場</h3>${p.steps.map(x=>`<div class="transaction"><b>${esc(x.date.slice(5))}</b><span>${x.planned?'已計畫 · ':''}${x.drop_name?'丟 '+esc(x.drop_name):'用空位'} → ${x.release_only?'騰位供 IL 回歸':`撿 <b>${esc(x.add_name)}</b> · ${esc(x.nba_team)}`}</span></div>`).join('')}<small>剩餘 add ${p.remaining} · 適配 ${p.gain.toFixed(2)}${p.steps.some(x=>!x.confirmed)?' · 含歸屬待確認球員':''}</small>${p.gain<=0?'<small>未改善模擬，建議保留原名單。</small>':''}<details><summary>操作後週曆</summary><div class="plan-week">${week.map((d,j)=>`<div><b>${['一','二','三','四','五','六','日'][j]} ${d.slice(5)}</b>${p.steps.filter(x=>x.date===d).map(x=>`<p>＋${esc(x.add_name)}</p>`).join('')}${p.calendar.find(x=>x.date===d)?.lineup.map(x=>`<small>${esc(x.name)}</small>`).join('')||'<small>保留實績</small>'}</div>`).join('')}</div></details></article>`).join('')||'請選可丟棄球員並確認 add 額度。');html+='<details><summary>賽程與數據依據</summary>';html+=section('優先補強球隊',r.teams.slice(0,8).map(t=>`<div class="card"><b>${esc(t.team)}</b><small>${windows(t.windows)}</small></div>`).join('')||'尚無可補強球隊');
 html+=section('補強方向',`<b>${r.focus.map(c=>LABELS[CATS.indexOf(c)]).join('、')||'九項整體改善'}</b><small>已保存實績＋剩餘場次預測${r.missing_history.length?' · '+r.missing_history.length+' 天排陣未同步':''}</small>${scoreTable(r.before.tot,r.enemy.tot)}`);
html+='</details>';return html+'</div>';
}

function tradePage(){if(!teams().length)return empty();const other=opponent();return `<div class="field-row">${select('trade-opponent',teams().filter(t=>t!==S.team).map(t=>[t,teamName(t)]),other,'對手')}<div><label>比較基準</label><span class="tag">上季場均</span></div></div><section class="card"><div class="field-row"><div><h3>釋出</h3>${roster().map(p=>`<label class="row"><input class="trade-check" type="checkbox" name="give" value="${esc(pkey(p))}">${esc(p.name)}</label>`).join('')}</div><div><h3>加入</h3>${roster(other).map(p=>`<label class="row"><input class="trade-check" type="checkbox" name="take" value="${esc(pkey(p))}">${esc(p.name)}</label>`).join('')}</div></div><button class="primary" data-action="trade-calculate">比較九項</button><div id="trade-result"></div></section>`;}
function simPlayers(rows){return rows.map(p=>({...structuredClone(p),id:pkey(p)}));}
function ensureSim(){if(S.sim&&S.sim.context?.my_team===S.team&&S.sim.context?.opp_team===opponent()&&JSON.stringify(S.sim.week_dates)===JSON.stringify(weekDates(S.date)))return;const dates=weekDates(S.date),my=simPlayers(uniqueRoster(roster())),opp=simPlayers(uniqueRoster(roster(opponent())));for(const [side,rows,t] of [['my',my,S.team],['opp',opp,opponent()]])for(const d of dates)for(const p of archives()[d]?.teams?.[t]||[])if(!rows.some(r=>pkey(r)===pkey(p)))rows.push({...structuredClone(p),id:pkey(p),historical_only:true});S.simDay=Math.max(0,dates.indexOf(S.date));S.sim={format:'fantasy-gm-simulation',version:1,include_actual:true,week_dates:dates,selected_day:0,context:{season:'2026-27',my_team:S.team,opp_team:opponent()},players:{my,opp},lineups:dates.map(d=>({my:d<=today()?archiveSlots(d,'my'):autoLineup(my.filter(p=>p.status!=='IL'&&!p.historical_only),d,S.model.schedule),opp:d<=today()?archiveSlots(d,'opp'):autoLineup(opp.filter(p=>p.status!=='IL'&&!p.historical_only),d,S.model.schedule)})),daily_choices:{my:{},opp:{}}};}
let simStatus=null,simStatusAt=0,simStatusPending=false;
async function refreshSimStatus(force=false){if(simStatusPending||(!force&&Date.now()-simStatusAt<25000))return;simStatusPending=true;try{simStatus=await api('/api/sim-status');simStatusAt=Date.now();if(S.page==='sim'&&!$('#dialog').open)render();}catch{simStatus=null;}finally{simStatusPending=false;}}
function editableStats(p,d){return canEditPrediction(d,p.team||p.TEAM_ABBREVIATION,simStatus);}
function predictedStats(p,side,d){const i=S.sim.week_dates.indexOf(d),custom=S.sim.daily_choices?.[side]?.[`${pkey(p)}::${i}`]?.custom;return custom?stats(custom):null;}
function simDaily(side,d){const sim=S.sim,team=side==='my'?sim.context.my_team:sim.context.opp_team;if(d<=today()){const rows=archives()[d]?.teams?.[team];return {known:!!rows,stats:total((rows||[]).filter(p=>p.status==='active'&&((sim.include_actual&&p.daily_stats!=null)||editableStats(p,d))).map(p=>editableStats(p,d)?predictedStats(p,side,d):sim.include_actual?stats(p.daily_stats):null)),rows};}const i=sim.week_dates.indexOf(d),ids=Object.values(sim.lineups[i][side]).filter(Boolean);return {known:true,stats:total(ids.map(id=>{const p=sim.players[side].find(p=>p.id===id);return p&&(S.model.schedule[p.team]||[]).includes(d)?predictedStats(p,side,d):null;}))};}
function simPlannedAdds(){return S.sim?.players.my.filter(p=>p.added===true)||[];}
function simAddBudget(){const q=league().yahoo_adds?.[S.team],remaining=S.page==='planner'?(plannerRemaining??(q?.week===weekDates(plannerStart)[0]?q.remaining:4)):(q?.week===S.sim.week_dates[0]?q.remaining:null);return `<small class="${remaining!=null&&simPlannedAdds().length>remaining?'error':''}">已計畫 add ${simPlannedAdds().length}${remaining==null?'':' / '+remaining}</small>`;}
function plannerSchedule(p,d){const schedule=S.model.schedule||{},known=Array.isArray(schedule[p.team]),games=schedule[p.team]||[],has=games.includes(d);return `<span class="player-game ${known?(has?'scheduled':'off'):'unknown'}">${esc(p.team||'球隊待確認')} · ${known?(has?'有賽程':'無賽程'):'賽程未載入'}</span><span class="player-week">${S.sim.week_dates.map((day,i)=>`<i class="${known?(games.includes(day)?'scheduled':'off'):'unknown'} ${day===d?'current':''}" title="${day} ${known?(games.includes(day)?'有賽程':'無賽程'):'賽程未載入'}">${['一','二','三','四','五','六','日'][i]}</i>`).join('')}</span>`;}
function plannerBoard(){
 const sim=S.sim,d=sim.week_dates[S.simDay],past=d<today();
 const dated=(side)=>{const team=side==='my'?S.team:opponent();return past?(archives()[d]?.teams?.[team]||[]):sim.players[side];};
 const face=(p,side,slot)=>p?`<button class="planner-player ${side==='opp'?'opponent':''}" data-action="planner-player" data-id="${esc(pkey(p))}" data-side="${side}" data-slot="${slot||''}" draggable="${!past&&plannerTrayOpen}" data-drag-player="${esc(pkey(p))}" data-drag-side="${side}">${photo(p)}<span>${esc(p.name)}<small>${esc((p.eligible||[]).join('/'))}</small>${plannerSchedule(p,d)}</span></button>`:`<div class="planner-player vacancy" aria-label="${side==='my'?'我的':'對手'} ${slot} 拖曳位置">${slot.startsWith('UTIL')?'不限位置':'拖曳至此'}</div>`;
 const daySlots=side=>{if(!past)return sim.lineups[S.simDay][side];return archiveSlots(d,side);};
 let html=`<div class="week-strip">${sim.week_dates.map((day,i)=>`<button class="${i===S.simDay?'active':''}" data-action="sim-day" data-day="${i}">${['一','二','三','四','五','六','日'][i]}<br>${day.slice(5)}</button>`).join('')}</div><div class="planner-board-head"><span>我的先發</span><span>位置</span><span>對手先發</span></div>`;
 for(const slot of SLOTS){html+=`<div class="planner-board-row">${['my','opp'].map((side,i)=>{const id=daySlots(side)[slot],p=dated(side).find(p=>pkey(p)===id),cell=`<div class="planner-dropzone" data-drop-side="${side}" data-drop-slot="${slot}">${face(p,side,slot)}</div>`;return i?`<b>${slot.replace(/[12]$/,'')}</b>`+cell:cell;}).join('')}</div>`;}
 html+=`<details class="planner-bench" ${plannerTrayOpen?'open':''}><summary>調整名單 · 板凳／IL</summary>${['my','opp'].map(side=>{const bench=dated(side).filter(p=>!Object.values(daySlots(side)).includes(pkey(p))),onIL=p=>p.status==='IL'&&(!p.return_date||d<p.return_date);return `<div class="planner-roster-tray"><small>${side==='my'?'我的球隊':'對手球隊'}</small><div class="planner-bench-zone" data-drop-side="${side}" data-drop-slot="BN"><b>拖回板凳</b><div class="planner-bench-grid">${bench.filter(p=>!onIL(p)).map(p=>face(p,side,'')).join('')}</div></div><div class="planner-il-zone" data-drop-side="${side}" data-drop-slot="IL"><b>IL · 回歸前保留</b><div class="planner-bench-grid">${bench.filter(onIL).map(p=>face(p,side,'')).join('')}</div></div></div>`;}).join('')}</details>`;
 if(!past)html+='<div class="row wrap"><button data-action="sim-add-player">＋ 計畫 add</button><button data-action="planner-auto-day">排當天</button></div>';
 return html+simAddBudget()+`<small>${past?'保留已保存排陣':'展開底部名單後拖曳；點頭像查看或編輯數據。'}</small>`;
}
function archiveSlots(d,side){const out={},team=side==='my'?S.team:opponent();for(const p of archives()[d]?.teams?.[team]||[]){if(p.status!=='active')continue;const raw=String(p.slot||'').toUpperCase(),slot=raw==='C'?(!out.C1?'C1':'C2'):raw==='UTIL'?(!out.UTIL1?'UTIL1':'UTIL2'):raw;if(SLOTS.includes(slot)&&!out[slot])out[slot]=pkey(p);}return out;}
function plannerMove(id,side,slot){const d=S.sim.week_dates[S.simDay],p=S.sim.players[side].find(p=>pkey(p)===id);if(!p||d<today())throw Error('過去日期不能更改');if(p.historical_only&&d>today())throw Error('這位球員只有歷史排陣紀錄');if(p.added&&p.acquired_date&&d<p.acquired_date)throw Error('此球員尚未到計畫加入日期');if(d===today()&&(S.model.schedule[p.team]||[]).includes(d)&&!editableStats(p,d))throw Error('這場已開打或尚未確認狀態');if(slot==='IL'&&p.status!=='IL')throw Error('這位球員未列在傷兵名單');if(!['BN','IL'].includes(slot)&&(!(S.model.schedule[p.team]||[]).includes(d)||!eligible(p,slot)))throw Error('此日沒有賽程或位置不符');const slots=S.sim.lineups[S.simDay][side],old=SLOTS.find(k=>slots[k]===id),other=slots[slot];if(other&&other!==id){const q=S.sim.players[side].find(p=>pkey(p)===other);if(q&&d===today()&&!editableStats(q,d))throw Error('原位置球員已開打');if(old&&q&&eligible(q,old))slots[old]=other;else if(old)slots[old]=null;}else if(old)slots[old]=null;if(!['BN','IL'].includes(slot))slots[slot]=id;if(slot==='IL'){delete p.return_date;for(let i=0;i<7;i++)if(S.sim.week_dates[i]>=today())for(const k of SLOTS)if(S.sim.lineups[i][side][k]===id)S.sim.lineups[i][side][k]=null;}if(p.status==='IL'&&!['BN','IL'].includes(slot)&&(!p.return_date||d<p.return_date))p.return_date=d;plannerResult=null;render();}
function simPage(plannerMode=false){if(!teams().length)return empty();ensureSim();if(plannerMode)return plannerBoard();const sim=S.sim,days=sim.week_dates,d=days[S.simDay],a=days.map(d=>simDaily('my',d)),b=days.map(d=>simDaily('opp',d)),actual=d<=today(),side=S.simSide,team=side==='my'?sim.context.my_team:sim.context.opp_team;let rows=actual?(archives()[d]?.teams?.[team]||[]):sim.players[side];const activeIds=actual?rows.filter(p=>p.status==='active').map(p=>p.id):Object.values(sim.lineups[S.simDay][side]);return `${plannerMode?'':`<div class="field-row">${select('sim-opponent',teams().filter(t=>t!==S.team).map(t=>[t,teamName(t)]),opponent(),'對手')}${dateControl('sim-date',S.date)}</div>`}${scoreCard(total(a.map(x=>x.stats)),total(b.map(x=>x.stats)),opponent(),a.every(x=>x.known)&&b.every(x=>x.known))}<details><summary>每週九項</summary>${scoreTable(total(a.map(x=>x.stats)),total(b.map(x=>x.stats)))}</details><div class="row"><input id="sim-save-name" placeholder="模擬名稱" maxlength="80"><button class="primary" data-action="sim-save">儲存</button><button data-action="sim-open">開啟</button><button data-action="sim-actual">載入實績</button><button data-action="sim-reset-data">清空模擬資料</button></div><div class="week-strip">${days.map((day,i)=>`<button class="${i===S.simDay?'active':''}" data-action="sim-day" data-day="${i}">${['一','二','三','四','五','六','日'][i]}<br>${day.slice(5)}</button>`).join('')}</div><div class="segment"><button data-action="sim-side" data-side="my" class="${side==='my'?'active':''}">我方</button><button data-action="sim-side" data-side="opp" class="${side==='opp'?'active':''}">對手</button></div><small>${actual?'已開賽顯示實績；未開賽留白，可編輯預測。':'點球員編輯預測。'}</small><section class="card">${actual?(rows.length?rows.map(p=>row(p,editableStats(p,d)?predictedStats(p,side,d):sim.include_actual&&p.daily_stats?stats(p.daily_stats):null,editableStats(p,d)?`<button data-action="sim-edit" data-id="${esc(pkey(p))}">編輯</button>`:`<span class="tag">${esc(p.slot||p.status)}</span>`)).join(''):'<p class="muted">此日尚無排陣，請同步所選週。</p>'):SLOTS.map(slot=>{const id=sim.lineups[S.simDay][side][slot],p=rows.find(p=>p.id===id);return `<div class="lineup-row"><b>${slot.replace('UTIL','U')}</b><button data-action="${p?'sim-edit':'sim-slot'}" data-id="${p?esc(p.id):''}" data-slot="${slot}">${p?esc(p.name):'空位'}</button><button data-action="sim-clear" data-slot="${slot}" aria-label="清空">×</button></div>`;}).join('')}${!actual?'<div class="row"><button data-action="sim-auto">自動排程</button><button data-action="sim-add-player">＋ 計畫 add</button></div>':''}</section>${simAddBudget()}`;}
