let analysisWeek='',analysisKey='',analysisStamp='',analysisResult=null,analysisError='';
async function loadLeagueAnalysis(key){analysisKey=key;analysisResult=null;analysisError='';try{const r=await api('/api/league-analysis',{method:'POST',body:{week:key,profile:S.payload}});if(key===analysisKey)analysisResult=r;}catch(e){analysisError=e.message;}if(S.page==='results')render();}
function leagueAnalysisView(){const weeks=[...new Set([...Object.keys(league().yahoo_matchups||{}),...Object.keys(S.payload.files['league_results.json']?.weeks||{}),...Object.keys(archives()).map(d=>weekDates(d)[0])])].sort().reverse();if(!weeks.length)return section('全聯盟九項比較','尚無保存的週數據。');const key=weeks.includes(analysisWeek)?analysisWeek:weeks[0];const stamp=JSON.stringify([league().yahoo_matchups?.[key]?.updated_at,S.payload.files['league_results.json']?.weeks?.[key]?.updated_at,league().sync_updated_at]);if(analysisKey!==key||analysisStamp!==stamp){analysisStamp=stamp;loadLeagueAnalysis(key);}let html=select('analysis-week',weeks.map(w=>[w,w]),key,'比較週次');if(!analysisResult)return section('全聯盟九項比較',html+`<p>${esc(analysisError||'整理九項與實際出賽場次…')}</p>`);const data=analysisResult;for(const [field,summary,title] of [['totals','total_summary','各隊週總數'],['per_game','game_summary','每球員出賽場次平均']]){html+=`<h3>${title}</h3><div class="table-scroll"><table><thead><tr><th>球隊</th><th>場次</th>${LABELS.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>`;for(const row of data[field])html+=`<tr><td>${esc(teamName(row.team))}</td><td>${row.games??'—'}</td>${CATS.map(c=>`<td>${format(row.values[c],c)}</td>`).join('')}</tr>`;for(const [k,label] of [['mean','聯盟平均'],['std','標準差']])html+=`<tr><th>${label}</th><td>—</td>${CATS.map(c=>`<td>${format(data[summary][c]?.[k],c)}</td>`).join('')}</tr>`;html+='</tbody></table></div>';}html+='<small>場次優先使用 Yahoo Matchup Games Played；舊紀錄才依每日先發重建。FG／FT 用總命中÷總出手。跨隊等權平均、母體標準差；缺資料不補零。</small>';if(data.note)html+=`<p>${esc(data.note)}</p>`;return section('全聯盟九項比較',html);}
function resultsPage(){if(!teams().length)return empty();const w=league().matchup_schedule?.weeks||[];let html=leagueAnalysisView()+`${dateControl()}`;const a=weekActual(S.team),b=weekActual(opponent());html+=actualScoreCard();html+=section('每週對手',w.length?`<table><thead><tr><th>週</th><th>日期</th><th>對手</th></tr></thead><tbody>${w.map(x=>`<tr><td>${x.week}</td><td>${esc(x.start.slice(5))}</td><td>${esc(teamName(x.opponents[S.team]||'—'))}</td></tr>`).join('')}</tbody></table>`:'<small>尚未同步對戰表。</small>');const stored=S.payload.files['league_results.json']?.weeks||{},table=new Map(teams().map(t=>[t,{w:0,l:0,t:0}]));for(const week of Object.values(stored).filter(w=>w.final)){for(const [t,r] of Object.entries(week.teams||{})){const enemy=week.teams[r.opponent];if(!table.has(t)||!enemy)continue;const c=compare(stats(r.totals),stats(enemy.totals));table.get(t).w+=c.wins;table.get(t).l+=c.losses;table.get(t).t+=c.ties;}}return html+section('積分',`<table><thead><tr><th>球隊</th><th>勝</th><th>敗</th><th>和</th></tr></thead><tbody>${[...table].sort((a,b)=>b[1].w-a[1].w).map(([t,x])=>`<tr><td>${esc(teamName(t))}</td><td>${x.w}</td><td>${x.l}</td><td>${x.t}</td></tr>`).join('')}</tbody></table><small>H2H Each Category；僅計入已保存的結算週。</small>`);}
function currentRosters(){return teams().map(t=>section(esc(teamName(t)),`<div class="player-grid roster-gallery">${roster(t).map(p=>`<div class="player-tile">${photo(p)}<div class="player-name">${esc(p.name)}</div><small>${esc([p.team,(p.eligible||[]).join('/'),p.status==='IL'?'IL':''].filter(Boolean).join(' · '))}</small></div>`).join('')}</div>`)).join('')||'<small>尚無名單，請先同步 Yahoo。</small>';}
function dataPage(){const days=Object.keys(archives()).sort().reverse();return currentRosters()+section('資料來源',`<div class="row between"><span>Yahoo 名單</span><b>${teams().length} 隊</b></div><div class="row between"><span>每日快照</span><b>${days.length} 天</b></div><div class="row between"><span>場均基準</span><b>${esc(S.model.season)}</b></div><small>${esc(league().sync_updated_at||'尚未同步')}</small><button data-action="import">匯入 JSON／同步網址</button><button data-action="export">下載備份</button>`)+section('已存模擬',Object.keys(S.payload.files['simulations.json']||{}).map(n=>`<button class="quiet" data-action="sim-load" data-name="${esc(n)}">${esc(n)}</button>`).join('')||'<small>尚無存檔。</small>');}
function settingsPage(){return section('Google Drive',`<div class="row between"><span>${esc(S.session?.user?.name||'尚未登入')}</span><span class="tag">${S.session?.user?'已登入':'本機'}</span></div>${S.session?.user?'<button data-action="cloud">立即同步</button><button class="quiet" data-action="logout">登出</button>':`<button class="primary" data-action="login">使用 Google 登入</button>`}<div class="field-row"><div><label for="league-id">聯盟 ID</label><input id="league-id" inputmode="numeric" value="${esc(S.league)}" maxlength="10"></div><div><label>聯盟</label><button data-action="league-change">開啟</button></div></div><small id="cloud-error">${esc(S.cloudError)}</small>`)+section('Yahoo 同步',`<button data-action="roster-sync">同步整週排陣與實績</button><button data-action="bookmark">取得手機書籤</button><button data-action="import">匯入同步網址／備份</button><details><summary>第一次設定</summary><div class="stack"><p class="muted">1. 在瀏覽器與 App 登入同一 Google 帳號。<br>2. 將同步書籤存入瀏覽器。<br>3. 在 Yahoo 聯盟執行書籤，選擇日期。<br>4. 首次核對名單，保存後回 App 按 Y。</p></div></details>`)+section('外觀',`<button data-action="theme">${document.body.classList.contains('dark')?'切換淺色':'切換深色'}</button><details><summary>安裝至主畫面</summary><div class="stack"><p class="muted">手機用 HTTPS 開啟新版網址，再從瀏覽器選「加入主畫面」。本機 localhost 僅供電腦預覽，手機需使用可連線的 HTTPS 部署。</p></div></details>`)+section('備份',`<button data-action="export">下載備份</button><button data-action="import">匯入</button><small>新版沿用既有紀錄格式，匯入會先驗證，不會直接覆寫雲端。</small>`)+section('App 預覽 0.1',`<small>進階交易推薦、完整釋出球員最佳化與自訂預測仍在原版。</small><button data-action="legacy">開啟原版</button>`);}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function changed({renderPage=false}={}){S.dirty=true;S.cloudError='';persist();renderContext();if(renderPage)render();if(S.session?.user&&S.cloudReady){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>queueCloudSave(),400);}}
function queueCloudSave(){saveChain=saveChain.then(async()=>{if(!S.dirty||!S.cloudReady)return;S.pending=true;renderContext();const payload=structuredClone(S.payload),revision=S.revision;try{const result=await api('/api/cloud',{method:'POST',body:{league:S.league,revision,payload}});S.revision=result.revision;if(JSON.stringify(S.payload)===JSON.stringify(payload))S.dirty=false;persist();}catch(e){S.cloudError=e.message;S.cloudReady=false;toast(e.message);}finally{S.pending=false;renderContext();}});return saveChain;}
async function cloudSync({silent=false}={}){if(S.pending){if(!silent)toast('正在同步，請稍候');return;}if(!S.session?.user){if(!silent)dialog('連接 Drive','<p class="muted">先登入相同 Google 帳號，才能載入跨裝置紀錄。</p><button class="primary" data-action="login">登入 Google</button>');return;}if(!/^\d{1,10}$/.test(S.league)){if(!silent)toast('請先在設定輸入聯盟 ID');return;}S.pending=true;S.cloudReady=false;renderContext();try{const result=await api('/api/cloud?league='+S.league),remote=result.profile;if(remote){const validated=(await api('/api/validate',{method:'POST',body:remote.payload})).payload;if(S.dirty&&remote.revision!==S.revision){S.cloudReady=false;S.cloudError='雲端有新版本';if(!silent)dialog('保留哪個版本？','<p class="muted">本機修改已保留。先下載備份，再載入雲端，避免覆寫。</p><div class="stack"><button data-action="export">下載本機備份</button><button data-action="cloud-replace">載入雲端</button></div>');return;}if(!S.dirty){S.payload=validated;if(validated.prefs.visual_theme)document.body.classList.toggle('dark',validated.prefs.visual_theme!=='簡約淺色');S.revision=remote.revision;S.weights=Object.fromEntries(CATS.map(c=>[c,S.payload.prefs['nc_weight_'+c]??1]));S.sim=null;S.cloudError='';persist();render();}}else if(S.revision){throw Error('雲端紀錄不存在，先保留本機資料');}S.cloudReady=true;if(S.dirty)await queueCloudSave();if(!silent&&!S.cloudError)toast(S.dirty?'已保留本機修改':'已讀取 Drive 紀錄；Yahoo 比分以頁面同步時間為準');}catch(e){S.cloudError=e.message;S.cloudReady=false;if(!silent)toast(e.message);}finally{S.pending=false;renderContext();}}
async function importValue(value){let payload;if(value?.schema===1&&value.files)payload=value;else if(value?.payload?.files)payload=value.payload;else if(value?.schema===1&&value.teams&&Array.isArray(value.teams)){const lid=String(value.league);if(S.league&&S.league!==lid){persist();S.league=lid;S.payload=fresh();S.revision=0;S.cloudReady=false;}else S.league=lid;const normalized=await api('/api/normalize',{method:'POST',body:{snapshot:value,current:league()}});payload=structuredClone(S.payload);payload.files['league_rosters.json']=normalized.league;}else if(value?.teams&&!Array.isArray(value.teams)){payload=structuredClone(S.payload);payload.files['league_rosters.json']=value;S.league=String(value.sync_league||S.league);}else throw Error('請匯入聯盟備份或書籤同步資料');const checked=(await api('/api/validate',{method:'POST',body:payload})).payload;const importedLeague=String(checked.files['league_rosters.json']?.sync_league||'');if(importedLeague&&importedLeague!==S.league){persist();S.league=importedLeague;S.revision=0;S.cloudReady=false;}const old=S.payload;S.payload=checked;S.team=Object.keys(league().teams||{})[0]||'';try{changed();}catch(e){S.payload=old;throw e;}S.sim=null;if(!archives()[S.date])S.date=Object.keys(archives()).sort().at(-1)||S.date;persist();render();toast('名單已匯入本機');if(S.session?.user)await cloudSync();}
async function decodeLink(text){const u=new URL(text);const hash=u.hash;if(!/^#yahoo-roster(?:-gzip)?=/.test(hash))throw Error('網址沒有同步資料');const raw=atob(hash.slice(hash.indexOf('=')+1));let bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));if(bytes.length>2e6)throw Error('資料過大');if(hash.startsWith('#yahoo-roster-gzip=')){if(!globalThis.DecompressionStream)throw Error('此瀏覽器無法解壓，請改匯入 JSON');const r=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')).getReader();const chunks=[];let count=0;while(true){const {done,value}=await r.read();if(done)break;count+=value.length;if(count>MAX_IMPORT){await r.cancel();throw Error('資料過大');}chunks.push(value);}bytes=new Uint8Array(count);let i=0;for(const c of chunks){bytes.set(c,i);i+=c.length;}}return JSON.parse(new TextDecoder().decode(bytes));}
const MAX_IMPORT=4e6;
async function action(button){const a=button.dataset.action,id=button.dataset.id;switch(a){case 'sim-add-player':{const owned=new Set(teams().flatMap(t=>roster(t)).map(p=>pkey(p)));dialog('計畫 add',`<label for="sim-add-search">球員</label><input id="sim-add-search" placeholder="搜尋自由球員姓名"><div id="sim-add-results"></div>`);const update=()=>{const q=$('#sim-add-search').value.toLowerCase().trim(),found=Object.values(S.pool).filter(p=>q&&p.PLAYER_NAME.toLowerCase().includes(q)&&!owned.has(String(p.PLAYER_ID))&&!S.sim.players.my.some(r=>pkey(r)===String(p.PLAYER_ID))).slice(0,15);$('#sim-add-results').innerHTML=found.map(p=>`<button class="quiet" data-action="sim-plan-add" data-id="${p.PLAYER_ID}">${esc(p.PLAYER_NAME)} · ${esc(p.team||p.TEAM_ABBREVIATION)}</button>`).join('');};$('#sim-add-search').oninput=update;break;}
case 'sim-plan-add':{const p=S.pool[id],d=S.sim.week_dates[S.simDay];if(!p||d<today())throw Error('不能在過去新增球員');const owned=teams().flatMap(t=>roster(t));if(owned.some(r=>pkey(r)===id))throw Error('此球員已屬於聯盟球隊');if(S.sim.players.my.some(r=>pkey(r)===id))throw Error('已在模擬名單');const meta=league().player_meta?.[id]||{},positions=meta.eligible||p.eligible||[];S.sim.players.my.push({id,nba_id:Number(id),name:p.PLAYER_NAME,team:meta.team||p.team||p.TEAM_ABBREVIATION,eligible:positions.filter(x=>['PG','SG','SF','PF','C'].includes(x)),status:'active',added:true,acquired_date:d});plannerResult=null;$('#dialog').close();render();toast('已列入計畫 add；可安排位置，尚未執行 Yahoo 加人');break;}
case 'planner-player':{S.simSide=button.dataset.side;const side=S.simSide,p=S.sim.players[side].find(p=>pkey(p)===id),d=S.sim.week_dates[S.simDay],team=side==='my'?S.team:opponent();if(!p)return;if(d<today()||!editableStats(p,d)){const observed=archives()[d]?.teams?.[team]?.find(p=>pkey(p)===id);dialog(p.name,statline(observed?.daily_stats?stats(observed.daily_stats):null)+'<small>已保存實績；尚無資料時留白。</small>');}else if(p.added){dialog(p.name,`<button data-action="sim-edit" data-id="${esc(id)}">編輯數據</button><button data-action="planner-remove-add" data-id="${esc(id)}">取消計畫 add</button>`);}else{await action({dataset:{action:'sim-edit',id}});}break;}
case 'planner-remove-add':{const p=S.sim.players[S.simSide].find(p=>pkey(p)===id);if(!p?.added)return;S.sim.players[S.simSide]=S.sim.players[S.simSide].filter(p=>pkey(p)!==id);for(const line of S.sim.lineups)for(const slot of SLOTS)if(line[S.simSide][slot]===id)line[S.simSide][slot]=null;plannerResult=null;$('#dialog').close();render();break;}
case 'planner-auto-day':{const d=S.sim.week_dates[S.simDay];if(d<=today())throw Error('今天及過去日期保留排陣，請逐格調整未開賽球員');for(const side of ['my','opp'])S.sim.lineups[S.simDay][side]=autoLineup(S.sim.players[side].filter(p=>!p.historical_only).filter(p=>!p.added||!p.acquired_date||p.acquired_date<=d).filter(p=>p.status!=='IL'||p.return_date&&p.return_date<=d).map(p=>({...p,status:'active'})),d,S.model.schedule);plannerResult=null;render();break;}
case 'planner-drop':plannerDrops=plannerDrops.includes(id)?plannerDrops.filter(k=>k!==id):[...plannerDrops,id];plannerResult=null;render();break;case 'planner-week':{const d=new Date(plannerStart+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+Number(button.dataset.offset));plannerStart=d.toISOString().slice(0,10);S.date=plannerStart;S.opponent='';S.sim=null;plannerRemaining=null;plannerResult=null;render();break;}case 'strategy-owned':S.strategyIncludeOwned=!S.strategyIncludeOwned;render();break;case 'strategy-retry':await loadStrategySeason();break;case 'strategy-reset':S.strategyPosition='';render();break;case 'planner-analyze':{if(!league().matchup_schedule?.weeks?.find(w=>w.start<=plannerStart&&w.end>=plannerStart)?.opponents?.[S.team])throw Error('請先同步此週 Yahoo 對手');plannerDrops=[...new Set(plannerDrops)].filter(id=>uniqueRoster(roster()).some(p=>pkey(p)===id));plannerResearch=$('#planner-research').checked;const remaining=Number($('#planner-remaining').value);plannerRemaining=remaining;plannerTrayOpen=false;plannerBusy=true;render();try{plannerResult=await api('/api/planner-workflow',{method:'POST',body:{profile:S.payload,team:S.team,opponent:opponent(),start:plannerStart<today()&&weekDates(plannerStart).includes(today())?today():plannerStart,drops:plannerDrops,remaining,research:plannerResearch,layout:S.sim}});}finally{plannerBusy=false;render();$('#planner-analysis')?.scrollIntoView({behavior:'smooth',block:'start'});}break;}case 'apply-weights':changed();render();break;case 'roster-sync':await yahooSync(false);break;case 'go':navigate(button.dataset.page);break;case 'star':{const ids=new Set(stars());ids.has(id)?ids.delete(id):ids.add(id);S.payload.files['player_watchlist.json']={ids:[...ids]};changed({renderPage:S.page==='watch'&&S.watchScope==='stars'});button.textContent=ids.has(id)?'★':'☆';button.setAttribute('aria-pressed',String(ids.has(id)));break;}case 'theme':document.body.classList.toggle('dark');S.payload.prefs.visual_theme=document.body.classList.contains('dark')?'黑色鏡面':'簡約淺色';changed();render();break;case 'legacy':{let target='https://fantasy-gm-bgjfjwjnxx8mbxjvajm2nk.streamlit.app/';if(embedded){try{const u=new URL(entryURL());u.searchParams.delete('app');u.searchParams.delete('phone_sync');u.hash='';window.parent.location.assign(u.href);break;}catch{}}window.open(target,'_blank','noopener');break;}case 'export':download('fantasy-gm-'+(S.league||'local')+'.json',S.payload);break;case 'import':dialog('匯入',`<div class="stack"><button data-action="file">選擇 JSON</button><label for="import-link">或貼上完整同步網址</label><textarea id="import-link" autocomplete="off" spellcheck="false"></textarea><button class="primary" data-action="import-link">匯入</button></div>`);break;case 'file':$('#import-file').click();break;case 'import-link':{const text=$('#import-link').value.trim();const data=text.startsWith('{')?JSON.parse(text):await decodeLink(text);await importValue(data);$('#dialog').close();break;}case 'cloud':setDrawer(false);await cloudSync();break;case 'adopt-import':{const pending=JSON.parse(localStorage.getItem('fgm-pwa-pending-import')||'null');if(!pending||pending.league!==S.league)throw Error('找不到此聯盟的待匯入資料');const merged=structuredClone(S.payload);merged.files['league_rosters.json']=pending.payload.files['league_rosters.json'];merged.files['player_watchlist.json']={ids:[...new Set([...stars(),...(pending.payload.files['player_watchlist.json']?.ids||[])])]};merged.files['simulations.json']={...(pending.payload.files['simulations.json']||{}),...(S.payload.files['simulations.json']||{})};await importValue(merged);localStorage.removeItem('fgm-pwa-pending-import');$('#dialog').close();break;}case 'dismiss-import':localStorage.removeItem('fgm-pwa-pending-import');$('#dialog').close();break;case 'cloud-replace':S.dirty=false;await cloudSync();$('#dialog').close();break;case 'login':setDrawer(false);if(S.dirty)localStorage.setItem('fgm-pwa-pending-import',JSON.stringify({league:S.league,payload:S.payload,at:Date.now()}));if(embedded){if(!S.session.googleConfigured)throw Error('本機預覽尚未設定 Google，仍可匯入與分析');const {flow}=await api('/api/login',{method:'POST',body:{league:S.league}});localStorage.setItem('fgm-drive-pending-v1',JSON.stringify({state:flow.state,verifier:flow.verifier,created:Date.now()}));dialog('登入 Google',`<a href="${safeURL(flow.url)}" target="_blank" rel="noopener">繼續使用 Google 登入 ↗</a>`);break;}if(!S.session.googleConfigured){dialog('Google 登入設定',`<p class="muted">新介面需要獨立的 Google 回呼網址。請將下列網址加入 OAuth 網頁用戶端：</p><p>${esc(S.session.callback)}</p><p class="muted">完成前仍可匯入、分析及保存本機紀錄。</p>`);}else location.assign('/auth/start?league='+encodeURIComponent(S.league));break;case 'logout':localStorage.removeItem('fgm-pwa-pending-import');localStorage.removeItem('fgm-drive-login-v1');localStorage.removeItem('fgm-drive-pending-v1');await api('/api/logout',{method:'POST',body:{}});location.reload();break;case 'league-change':{if(S.pending)throw Error('請等待目前同步完成');const lid=$('#league-id').value.trim();if(!/^\d{1,10}$/.test(lid))throw Error('聯盟 ID 請填數字');persist();S.league=lid;S.payload=fresh();S.revision=0;S.dirty=false;S.cloudReady=false;S.sim=null;restore();history.replaceState(null,'',embedded?location.pathname+location.search+'#page=settings':'/?league='+lid);render();await cloudSync({silent:true});break;}case 'bookmark':{const {bookmark}=await api('/api/bookmark');dialog('同步書籤',`<div class="stack"><p class="muted">新增「Fantasy GM 同步」書籤，網址換成以下內容。</p><textarea id="bookmark-code" readonly></textarea><button data-action="copy-bookmark">複製</button></div>`);$('#bookmark-code').value=bookmark;break;}case 'copy-bookmark':try{await navigator.clipboard.writeText($('#bookmark-code').value);toast('已複製');}catch{$('#bookmark-code').select();toast('請長按選取並複製');}break;case 'news':{const player=S.pool[id];dialog(player.PLAYER_NAME,`<div class="stack"><div class="hero"><div>${statline(player)}</div>${photo(player)}</div><div id="news-items">讀取新聞…</div></div>`);const generation=++S.generation;try{const data=await api('/api/news?player='+id);if(generation!==S.generation||!$('#dialog').open)return;$('#news-items').innerHTML=data.items.map(n=>`<div class="news-item"><a href="${safeURL(n.url)}" target="_blank" rel="noopener">${esc(n.title)}</a><small>${esc(n.time)}</small></div>`).join('')||'<small>暫無新聞。</small>';}catch(e){if($('#news-items'))$('#news-items').textContent=e.message;}break;}case 'trade-calculate':{const selected=name=>[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);const give=selected('give'),take=selected('take');const base=total(roster().map(p=>stats(profile(p))));const after=total([...roster().filter(p=>!give.includes(pkey(p))),...roster(opponent()).filter(p=>take.includes(pkey(p)))].map(p=>stats(profile(p))));$('#trade-result').innerHTML=scoreTable(after,base)+'<small>左：交易後；右：目前。上季場均試算。</small>';break;}case 'sim-edit':{await refreshSimStatus(true);const side=S.simSide,d=S.sim.week_dates[S.simDay],team=side==='my'?S.sim.context.my_team:S.sim.context.opp_team;const rows=S.page==='planner'?S.sim.players[side]:d<=today()?(archives()[d]?.teams?.[team]||[]):S.sim.players[side];const p=rows.find(p=>pkey(p)===id);if(!p||!editableStats(p,d))throw Error('這場已開打或尚未確認開賽狀態');const values=predictedStats(p,side,d);const labels={FGM:'FG 命中',FGA:'FG 出手',FTM:'FT 命中',FTA:'FT 出手',FG3M:'3PT',PTS:'PTS',REB:'REB',AST:'AST',STL:'ST',BLK:'BLK',TOV:'TO'};dialog(p.name+' · '+d,`<div class="field-row">${KEYS.map(k=>`<div><label for="forecast-${k}">${labels[k]}</label><input id="forecast-${k}" type="number" min="0" step="0.1" value="${values?.[k]??0}"></div>`).join('')}</div><button class="primary" data-action="sim-edit-save" data-id="${esc(id)}" data-side="${side}" data-date="${d}">套用預測</button>`);break;}
case 'sim-edit-save':{plannerResult=null;const side=button.dataset.side,d=button.dataset.date,team=side==='my'?S.sim.context.my_team:S.sim.context.opp_team;const p=(S.page==='planner'?S.sim.players[side]:d<=today()?(archives()[d]?.teams?.[team]||[]):S.sim.players[side]).find(p=>pkey(p)===id);await refreshSimStatus(true);if(!p||!editableStats(p,d))throw Error('比賽已開打或狀態未確認，未套用預測');const values=Object.fromEntries(KEYS.map(k=>[k,Number($('#forecast-'+k).value)]));if(Object.values(values).some(v=>!Number.isFinite(v)||v<0)||values.FGM>values.FGA||values.FTM>values.FTA)throw Error('數據須為非負數，命中不可大於出手');values['3PM']=values.FG3M;values.TO=values.TOV;S.sim.daily_choices[side]??={};S.sim.daily_choices[side][`${id}::${S.sim.week_dates.indexOf(d)}`]={profile:'manual',custom:values};$('#dialog').close();render();toast('預測已套用，按儲存可保存模擬');break;}
case 'sim-actual':S.sim.include_actual=true;render();break;case 'sim-reset-data':S.sim.include_actual=true;S.sim.daily_choices={my:{},opp:{}};render();toast('已清空預測，保留實績與排陣');break;case 'sim-side':S.simSide=button.dataset.side;render();break;case 'sim-day':S.simDay=Number(button.dataset.day);render();break;case 'sim-clear':if(S.sim.week_dates[S.simDay]<=today())return;S.sim.lineups[S.simDay][S.simSide][button.dataset.slot]=null;render();break;case 'sim-auto':for(let i=0;i<7;i++)if(S.sim.week_dates[i]>today())S.sim.lineups[i][S.simSide]=autoLineup(S.sim.players[S.simSide],S.sim.week_dates[i],S.model.schedule);render();break;case 'sim-slot':{const slot=button.dataset.slot,players=S.sim.players[S.simSide].filter(p=>(p.status!=='IL'||S.page==='planner')&&eligible(p,slot));dialog('安排 '+slot,players.map(p=>`<button class="quiet" data-action="sim-place" data-id="${esc(p.id)}" data-slot="${slot}">${esc(p.name)}</button>`).join('')||'<p>沒有符合位置的球員。</p>');break;}case 'sim-place':{const slots=S.sim.lineups[S.simDay][S.simSide];for(const k of SLOTS)if(slots[k]===id)slots[k]=null;slots[button.dataset.slot]=id;$('#dialog').close();render();break;}case 'sim-save':{const name=$('#sim-save-name').value.trim();if(!name)throw Error('請輸入模擬名稱');S.sim.selected_day=S.simDay;S.payload.files['simulations.json']??={};S.payload.files['simulations.json'][name]=structuredClone(S.sim);const validated=await api('/api/validate',{method:'POST',body:S.payload});S.payload=validated.payload;changed();if(S.session?.user&&S.cloudReady){clearTimeout(cloudTimer);await queueCloudSave();toast(S.dirty?'模擬已存本機，雲端尚未完成':'模擬已存至 Drive');}else toast('模擬已存本機');break;}case 'sim-open':dialog('已存模擬',Object.keys(S.payload.files['simulations.json']||{}).map(n=>`<button class="quiet" data-action="sim-load" data-name="${esc(n)}">${esc(n)}</button>`).join('')||'<p class="muted">尚無存檔。</p>');break;case 'sim-load':{const p=S.payload.files['simulations.json'][button.dataset.name];if(!p)throw Error('找不到模擬');S.team=p.context.my_team;S.opponent=p.context.opp_team;S.date=p.week_dates[0];S.sim=structuredClone(p);S.simDay=p.selected_day||0;$('#dialog').close();navigate('sim');break;}}}
function safeURL(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
async function yahooSync(scoreOnly=false){
 setDrawer(false);
 const unavailable=()=>dialog('Yahoo 同步',`<div class="stack"><p>此瀏覽器未連接同步擴充功能。手機請開啟 Yahoo 執行同步書籤。</p><a href="https://basketball.fantasysports.yahoo.com/nba/${encodeURIComponent(S.league)}" target="_blank" rel="noopener">開啟 Yahoo 聯盟 ↗</a><button data-action="bookmark">取得同步書籤</button></div>`);
 if(!embedded){unavailable();return;}
 if(S.yahooPending){toast('Yahoo 同步中');return;}S.yahooPending=true;toast('正在連接 Yahoo 同步工具…');
 const frame=document.createElement('iframe');frame.hidden=true;frame.title='Yahoo 同步接收器';
 const u=new URL(location.href);u.pathname=u.pathname.replace('/pwa.streamlit_host.fantasy_pwa/','/league_sync.league_sync/');u.hash='';frame.src=u.href;
 let timer;const clean=()=>{clearTimeout(timer);window.removeEventListener('message',receive);frame.remove();S.yahooPending=false;};
 const args={force:crypto.randomUUID(),league:S.league,date:today(),mapping:league().sync_mapping||null,compact:true,pwa:true,scoreOnly};
 const send=()=>frame.contentWindow.postMessage({type:'streamlit:render',args},location.origin);
 const receive=async e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin)return;
 if(e.data?.type==='streamlit:componentReady'){send();return;}
 if(e.data?.type!=='streamlit:setComponentValue')return;const v=e.data.value;
 if(v?.syncUnavailable){clean();unavailable();return;}if(v?.syncError){clean();toast(v.syncError);return;}
 if(v?.officialResults){if(scoreOnly)clean();try{if(v.league!==S.league)throw Error('聯盟不符');const r=await api('/api/normalize-results',{method:'POST',body:{results:v.officialResults,current:league()}});S.payload.files['league_rosters.json']=r.league;changed();render();toast('Yahoo 當週最新比分已更新');if(S.session?.user&&S.cloudReady)await queueCloudSave();}catch(e){toast(e.message);}return;}
 if(v?.snapshot){clean();try{if(v.snapshot.league!==S.league)throw Error('Yahoo 聯盟不符，未套用');const selected=S.team;await importValue(v.snapshot);if(teams().includes(selected)){S.team=selected;persist();render();}toast(v.snapshot.matchupResults?'Yahoo 名單與官方比分已更新':'名單已更新，但官方比分未取得；比分仍是舊快照');}catch(e){toast(e.message);}}
 };
 window.addEventListener('message',receive);frame.onload=send;document.body.appendChild(frame);timer=setTimeout(()=>{clean();toast('Yahoo 同步逾時，原資料保留');},120000);
}
$('#menu').onclick=()=>setDrawer(!document.body.classList.contains('drawer-open'));$('#scrim').onclick=()=>setDrawer(false);$('#dialog-close').onclick=()=>{$('#dialog').close();S.generation++;};$('#navigation').onclick=e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page);};$('#backup').onclick=()=>{setDrawer(false);download('fantasy-gm-backup.json',S.payload);};$('#sync').onclick=()=>yahooSync().catch(e=>toast(e.message));$('#refresh').onclick=async()=>{setDrawer(false);if(S.session.user)await cloudSync();else{render();toast('已重新整理本機紀錄');}};
document.addEventListener('keydown',e=>{if(e.key==='Escape')setDrawer(false);});window.addEventListener('popstate',e=>navigate(e.state?.page||(location.hash.startsWith('#page=')?location.hash.slice(6):rememberedPage()),{history:false}));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')cloudSync({silent:true});});setInterval(()=>{if(document.visibilityState==='visible')cloudSync({silent:true});},300000);setInterval(()=>{if(S.page==='sim'&&document.visibilityState==='visible')refreshSimStatus(true);},30000);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;b.disabled=true;try{await action(b);}catch(error){toast(error.message);}finally{if(b.isConnected)b.disabled=false;}});
$('#team').onchange=()=>{S.team=$('#team').value;plannerDrops=[];plannerRemaining=null;plannerResult=null;S.payload.prefs._my_team=S.team;S.sim=null;changed();render();};
$('#main').addEventListener('change',e=>{const el=e.target,id=el.id;if(el.name==='planner-drop'){plannerDrops=[...document.querySelectorAll('input[name="planner-drop"]:checked')].map(x=>x.value);plannerResult=null;$('#planner-analysis')?.replaceChildren();return;}if(id==='planner-research'){plannerResearch=el.checked;plannerResult=null;$('#planner-analysis')?.replaceChildren();return;}if(id==='planner-remaining'){plannerRemaining=Number(el.value);plannerResult=null;$('#planner-analysis')?.replaceChildren();return;}if(id==='planner-team'){S.team=el.value;S.opponent='';S.sim=null;plannerDrops=[];plannerResult=null;plannerRemaining=null;render();return;}if(id==='planner-start'){plannerStart=el.value;plannerRemaining=null;plannerResult=null;render();return;}if(id==='planner-opponent'){plannerResult=null;}if(id==='analysis-week'){analysisWeek=el.value;render();return;}if(id==='strategy-season'){S.strategySeason=el.value;S.strategyData=null;render();loadStrategySeason();return;}if(id==='strategy-position'){S.strategyPosition=el.value;render();return;}if(id==='remaining-adds'){const v=Number(el.value);if(el.value!==''&&Number.isInteger(v)&&v>=0&&v<=4){S.payload.prefs[addQuotaKey()]=v;changed();}return;}if(id==='date'||id==='sim-date'){if(!/^\d{4}-\d{2}-\d{2}$/.test(el.value))return;S.date=el.value;S.sim=null;persist();render();}if(['planner-opponent','trade-opponent','sim-opponent'].includes(id)){S.opponent=el.value;S.sim=null;render();}if(id==='watch-scope'){S.watchScope=el.value;render();}if(id==='calendar-mode'){S.calendarMode=el.value;render();}if(id.startsWith('weight-')){const cat=id.slice(7),v=Number(el.value);if(!Number.isFinite(v)||v<0||v>10){toast('權重範圍 0–10');return;}S.weights[cat]=v;S.payload.prefs['nc_weight_'+cat]=v;changed();}});
let searchTimer;$('#main').addEventListener('input',e=>{if(e.target.id!=='watch-search')return;S.watchSearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const cursor=e.target.selectionStart;render();const input=$('#watch-search');input?.focus();input?.setSelectionRange(cursor,cursor);},180);});
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>MAX_IMPORT)throw Error('備份超過 4 MB');await importValue(JSON.parse(await file.text()));$('#dialog').close();}catch(error){toast(error.message);}e.target.value='';};
async function init(){try{[S.session,S.model]=await Promise.all([api('/api/session'),api('/api/model')]);if(!S.league&&/^\d{1,10}$/.test(String(S.session.league||'')))S.league=String(S.session.league);S.players=S.model.players;S.pool=Object.fromEntries(S.players.map(p=>[String(p.PLAYER_ID),p]));S.base=baseline(S.players);restore();S.weights=Object.fromEntries(CATS.map(c=>[c,S.payload.prefs['nc_weight_'+c]??1]));const incomingURL=entryURL();const syncHash=/^#yahoo-roster/.test(new URL(incomingURL).hash)?incomingURL:null;const page=location.hash.startsWith('#page=')?location.hash.slice(6):rememberedPage();navigate(page,{history:false});if(syncHash){toast('正在驗證同步資料…');await importValue(await decodeLink(syncHash));clearIncomingHash();history.replaceState({page:S.page},'',embedded?location.pathname+location.search+'#page='+S.page:'/?league='+S.league+'#page='+S.page);}else if(S.session.user)await cloudSync({silent:true});if(S.session.user){try{const pending=JSON.parse(localStorage.getItem('fgm-pwa-pending-import')||'null');if(pending&&pending.league===S.league&&Date.now()-pending.at<86400000)dialog('剛才的匯入資料',`<div class="stack"><p class="muted">合併匯入名單與星號，保留雲端模擬。</p><button class="primary" data-action="adopt-import">合併保存</button><button data-action="dismiss-import">保留雲端</button></div>`);}catch{}}if(new URLSearchParams(location.search).get('login')==='failed')toast('登入未完成，請重新登入');if(!embedded&&'serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}catch(error){$('#main').innerHTML=`<div class="empty"><h2>暫時無法載入</h2><p>${esc(error.message)}</p><button data-action="reload">重試</button></div>`;const b=$('[data-action="reload"]');if(b)b.onclick=()=>location.reload();}}
init();

let plannerDrag=null,plannerTouch=null,plannerSuppressClick=false;
$('#main').addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-player]');if(!el)return;plannerDrag={id:el.dataset.dragPlayer,side:el.dataset.dragSide};e.dataTransfer.setData('text/plain',plannerDrag.id);});
$('#main').addEventListener('dragover',e=>{if(plannerDrag&&e.target.closest('[data-drop-side]'))e.preventDefault();});
$('#main').addEventListener('drop',e=>{const target=e.target.closest('[data-drop-side]');if(!target||!plannerDrag)return;e.preventDefault();const p=plannerDrag;plannerDrag=null;if(target.dataset.dropSide!==p.side)return;try{plannerMove(p.id,p.side,target.dataset.dropSlot);}catch(error){toast(error.message);}});
$('#main').addEventListener('dragend',()=>plannerDrag=null);
$('#main').addEventListener('touchstart',e=>{if(e.touches.length!==1)return;const el=e.target.closest('[data-drag-player]');if(!el||el.getAttribute('draggable')==='false')return;const touch=e.touches[0],state={id:el.dataset.dragPlayer,side:el.dataset.dragSide,x:touch.clientX,y:touch.clientY,active:false};state.timer=setTimeout(()=>{state.active=true;el.classList.add('drag-ready');},450);plannerTouch=state;},{passive:true});
$('#main').addEventListener('touchmove',e=>{const t=plannerTouch;if(!t||!e.touches.length)return;const touch=e.touches[0];if(!t.active&&Math.hypot(touch.clientX-t.x,touch.clientY-t.y)>9){clearTimeout(t.timer);plannerTouch=null;return;}if(t.active){e.preventDefault();document.querySelectorAll('.planner-drop-hover').forEach(x=>x.classList.remove('planner-drop-hover'));t.target=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('[data-drop-side]');if(t.target?.dataset.dropSide===t.side)t.target.classList.add('planner-drop-hover');}},{passive:false});
$('#main').addEventListener('touchend',e=>{const t=plannerTouch;plannerTouch=null;if(!t)return;clearTimeout(t.timer);document.querySelectorAll('.drag-ready,.planner-drop-hover').forEach(x=>x.classList.remove('drag-ready','planner-drop-hover'));if(t.active){e.preventDefault();plannerSuppressClick=true;setTimeout(()=>plannerSuppressClick=false,400);if(t.target?.dataset.dropSide===t.side)try{plannerMove(t.id,t.side,t.target.dataset.dropSlot);}catch(error){toast(error.message);}}},{passive:false});
$('#main').addEventListener('touchcancel',()=>{if(plannerTouch)clearTimeout(plannerTouch.timer);plannerTouch=null;document.querySelectorAll('.drag-ready,.planner-drop-hover').forEach(x=>x.classList.remove('drag-ready','planner-drop-hover'));});
$('#main').addEventListener('click',e=>{if(plannerSuppressClick){e.preventDefault();e.stopImmediatePropagation();}},true);

$('#main').addEventListener('toggle',e=>{if(!e.target.matches('.planner-bench'))return;plannerTrayOpen=e.target.open;document.body.classList.toggle('planner-tray-open',S.page==='planner'&&plannerTrayOpen);const enabled=plannerTrayOpen&&S.sim.week_dates[S.simDay]>=today();document.querySelectorAll('.planner-player[data-drag-player]').forEach(el=>el.draggable=enabled);},true);
